using SoulsFormats;using System.Numerics;using System.Text.Json;using System.Security.Cryptography;
static class MapAdditionalDoorsAudit {
static string Leaf(string p)=>Path.GetFileName(p.Replace('\\','/'));
static void Main(string[] args){string source=args[0],defs=args[1],output=args[2];Directory.CreateDirectory(output);var hashes=new Dictionary<string,string>();byte[] Read(string p){var path=Path.Combine(source,p);var b=File.ReadAllBytes(path);hashes[path]=Convert.ToHexStringLower(SHA256.HashData(b));return b;}
var game=BND3.Read(Read("param/GameParam/GameParam.parambnd.dcx"));var tables=new List<object>();
foreach(var table in new[]{"ObjectParam","ObjActParam","EquipParamGoods"}){var p=PARAM.Read(game.Files.Single(f=>Leaf(f.Name)==table+".param").Bytes);p.ApplyParamdef(PARAMDEF.XmlDeserialize(Path.Combine(defs,table+".xml")));var ids=table=="EquipParamGoods"?new[]{2021,2100}:table=="ObjectParam"?new[]{1317,1305,1308,1310}:new[]{1317,1305,1308,1310,11317,11305,11308,11310};tables.Add(new{table,Rows=p.Rows.Where(r=>ids.Contains((int)r.ID)).Select(r=>new{r.ID,r.Name,Cells=r.Cells.ToDictionary(c=>c.Def.InternalName,c=>Convert.ToString(c.Value,System.Globalization.CultureInfo.InvariantCulture))})});}
File.WriteAllText(Path.Combine(output,"source-params.json"),JsonSerializer.Serialize(tables,new JsonSerializerOptions{WriteIndented=true}));
var msgs=BND3.Read(Read("msg/ENGLISH/item.msgbnd.dcx"));File.WriteAllText(Path.Combine(output,"source-keys.json"),JsonSerializer.Serialize(msgs.Files.SelectMany(f=>FMG.Read(f.Bytes).Entries.Where(e=>e.ID>=2000&&e.ID<=2100).Select(e=>new{f.ID,f.Name,EntryID=e.ID,e.Text})),new JsonSerializerOptions{WriteIndented=true}));
foreach(string model in new[]{"o1317","o1305"}){var bytes=Read("obj/"+model+".objbnd.dcx");var bank=BND3.Read(bytes);var visual=FLVER2.Read(bank.Files.Single(f=>f.ID==200).Bytes);var animations=BND3.Read(bank.Files.Single(f=>f.ID==400).Bytes);var clips=animations.Files.Where(f=>f.ID<10000).Select(f=>{var a=SourceAnimation.Decode(animations.Files.Single(f=>f.ID==1000000).Bytes.ToArray(),f.Bytes.ToArray());return new{f.ID,f.Name,a.Duration,a.FrameCount,a.FrameDuration,Bones=a.Bones.Select((b,i)=>new{Index=i,b.Name,b.Parent,b.Translation,b.Scale}),Start=a.Sample(0),Middle=a.Sample(a.Duration*.5f),End=a.Sample(a.Duration)};}).ToArray();var physics=bank.Files.Single(f=>f.ID==300).Bytes.ToArray();var tag=new SourceCollision.Tag(physics);var bodies=tag.Items.Where(i=>i.Count==1&&tag.Name(i.Type)=="hkpRigidBody").Select(b=>{var text=tag.Reference(tag.Nested(b.Type,b.At,"name").At);var shape=tag.Reference(tag.Nested(b.Type,b.At,"collidable","shape").At);string type=tag.Name(shape.Type);var translated=type=="hkpConvexTranslateShape"?tag.Vector(tag.Nested(shape.Type,shape.At,"translation").At):Vector3.Zero;var child=type=="hkpConvexTranslateShape"?tag.Reference(tag.Nested(shape.Type,shape.At,"childShape","childShape").At):shape;return new{Name=SourceAnimation.DecodeBoneName(physics.AsSpan(text.At,text.Count-1).ToArray()),Type=type,Child=tag.Name(child.Type),Translation=translated,Half=tag.Name(child.Type)=="hkpBoxShape"?tag.Vector(tag.Nested(child.Type,child.At,"halfExtents").At):Vector3.Zero,Radius=BitConverter.ToSingle(physics,tag.Nested(child.Type,child.At,"radius").At),Rest=tag.Transform(tag.Nested(b.Type,b.At,"motion","motionState").At)};}).ToArray();File.WriteAllText(Path.Combine(output,model+"-assets.json"),JsonSerializer.Serialize(new{Model=model,Hash=Convert.ToHexStringLower(SHA256.HashData(bytes)),Files=bank.Files.Select(f=>new{f.ID,f.Name,Length=f.Bytes.Length}),Nodes=visual.Nodes.Select((n,i)=>new{Index=i,n.Name,n.ParentIndex,n.Translation,n.Rotation,n.Scale}),Dummies=visual.Dummies.Select(d=>new{d.ReferenceID,d.ParentBoneIndex,d.AttachBoneIndex,d.Position,d.Forward,d.Upward}),Meshes=visual.Meshes.Select(m=>new{m.MaterialIndex,m.Dynamic,Vertices=m.Vertices.Count,Nodes=m.Vertices.Select(v=>v.BoneIndices[0]).Distinct().ToArray(),m.BoneIndices}),Bodies=bodies,Clips=clips},new JsonSerializerOptions{WriteIndented=true,IncludeFields=true}));}
if(args.Length>3){var path=Path.Combine(args[3],"obj/o241013.objbnd.dcx");var raw=File.ReadAllBytes(path);hashes[path]=Convert.ToHexStringLower(SHA256.HashData(raw));var obj=BND4.Read(raw);var anim=BND4.Read(obj.Files.Single(f=>f.ID==400).Bytes);var tae=TAE.Read(anim.Files.Single(f=>TAE.Is(f.Bytes.ToArray())).Bytes);File.WriteAllText(Path.Combine(output,"native-door-animation.json"),JsonSerializer.Serialize(new{Clips=anim.Files.Where(f=>f.ID>=1000000000).Select(f=>{var p=new NativeAnimation.Pack(f.Bytes.ToArray());int a=p.Object("hkaSplineCompressedAnimation");return new{f.ID,f.Name,Duration=p.Float(a+16),Frames=p.Int(a+56)};}),Tae=tae.Animations.Select(a=>new{a.ID,a.AnimFileName,Events=a.Events.Select(e=>new{e.Type,e.StartTime,e.EndTime,Hex=Convert.ToHexString(e.GetParameterBytes(false))})})},new JsonSerializerOptions{WriteIndented=true}));}foreach(var(path,h)in hashes)if(Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(path)))!=h)throw new Exception("Input mutated");File.WriteAllText(Path.Combine(output,"asset-hashes.json"),JsonSerializer.Serialize(hashes,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("PASS source additional-door audit "+hashes.Count+" unchanged files");}}
